/**
 * Colors
 */
export type BaseColor =
  | 'neutral'
  | 'primary'
  | 'secondary'
  | 'accent'
  | 'info'
  | 'success'
  | 'warning'
  | 'error'

/**
 * Actions / Button
 */
export type ButtonStyle = 'outline' | 'dash' | 'soft' | 'ghost' | 'link'

export type ButtonModifier = 'wide' | 'block' | 'square' | 'circle'

export type ButtonBehavior = 'active' | 'disabled'
